-- Whether a received file is drawn inside the email body (a signature logo,
-- Content-Disposition: inline) rather than attached. Old rows stay NULL; new
-- rows from the app are real attachments (default 0), and the inbound parser
-- sets it from the MIME headers.
ALTER TABLE email_attachments ADD COLUMN is_inline TINYINT(1) NULL;
ALTER TABLE email_attachments ALTER COLUMN is_inline SET DEFAULT 0;

-- image001-style files whose raw email was checked on 2026-10-28: real
-- attachments (Shirlene Davis's kitchen drawing; files sent from the app) ...
UPDATE email_attachments SET is_inline = 0 WHERE id IN (8496, 6109, 6111);

